/* Local serial queue. Recovery never restarts interrupted work without consent. */
(()=>{
  const key='abrxs-processes-v1',labels={import:'Crear fichas',export:'Exportar fichas',assets:'Miniaturas y audio',visual:'Análisis visual',studio_context:'Exportar contexto',studio_suggest:'Sugerencias'};
  let tasks=[],runner=null,active=null,starting=false;
  try{tasks=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(tasks))tasks=[];}catch{}
  tasks.forEach(t=>{if(['running','queued','cancelling'].includes(t.status))t.status='interrupted';});
  const panel=document.createElement('section');panel.id='processPanel';panel.hidden=true;
  panel.innerHTML='<header><h2>Procesos</h2><button id="processClose">Cerrar</button></header><p>Un trabajo a la vez. Puedes revisar y reproducir fichas mientras exportamos. Reintentar conserva las exportaciones idénticas.</p><div id="processCards"></div>';
  document.body.append(panel);panel.querySelector('#processClose').onclick=()=>panel.hidden=true;
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function save(){try{localStorage.setItem(key,JSON.stringify(tasks.slice(-100)));}catch{}render();}
  function render(){panel.querySelector('#processCards').innerHTML=tasks.map(t=>`<article><strong>${escape(labels[t.payload.op]||t.payload.op)}</strong><small>${escape(t.projectName)} · ${escape(({queued:'En cola',running:'En curso',interrupted:'Interrumpido',failed:'Error',finished:'Terminado',cancelling:'Cancelando',cancelled:'Cancelado'})[t.status]||t.status)}</small><progress max="100" value="${Number(t.progress)||0}"></progress><p>${escape(t.detail||'En espera de ejecución')}</p><details><summary>Acciones y diagnóstico</summary><div>${!t.legacy&&['queued','interrupted','failed','cancelled'].includes(t.status)?`<button data-action="retry" data-id="${t.id}">Continuar / reintentar</button><button data-action="up" data-id="${t.id}">Priorizar</button>`:''}${['running','queued','cancelling'].includes(t.status)?`<button data-action="cancel" data-id="${t.id}">Cancelar</button>`:''}<button data-action="copy" data-id="${t.id}">Copiar resumen</button></div><pre>${escape(t.error||'Sin errores registrados.')}</pre></details></article>`).join('')||'<p>Todavía no hay procesos.</p>';}
  async function pump(){if(starting||active||!runner||state.running||window.AbrxsStudio?.busy)return;const task=tasks.find(t=>t.status==='queued'&&t.projectId===state.project?.id);if(!task)return;starting=true;active=task;task.status='running';task.started=Date.now();task.detail='Preparando el trabajo; esperando respuesta del motor';save();try{await runner(task);}catch(e){finish(false,String(e));}finally{starting=false;}}
  function finish(success,detail){if(!active)return;active.status=active.status==='cancelling'?'cancelled':success?'finished':'failed';active.error=success?'':String(detail||'Proceso interrumpido');active.detail=detail||(success?'Terminado y guardado':'No terminó; abre el diagnóstico');active.progress=success?100:active.progress;active=null;save();setTimeout(pump,0);}
  panel.onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const task=tasks.find(t=>t.id===b.dataset.id);if(!task)return;try{switch(b.dataset.action){case 'copy':await navigator.clipboard.writeText(`${labels[task.payload.op]} · ${task.projectName}\nEstado: ${task.status}\n${task.detail||''}\n${(task.error||'Sin errores').slice(-3000)}`);break;case 'up':if(task===active)break;tasks.splice(tasks.indexOf(task),1);tasks.unshift(task);break;case 'retry':if(task===active)break;task.status='queued';task.error='';break;case 'cancel':if(task===active){task.status='cancelling';task.detail='Cancelando el motor; esperando confirmación';save();await window.__TAURI__.core.invoke('cancel_job');}else task.status='cancelled';}}catch(error){task.error=String(error);}save();pump();};
  window.__TAURI__.event.listen('stage1-event',({payload:p})=>{if(!active)return;if(['progress','clip_start','notice','clip_error'].includes(p.event)){active.progress=p.progress??active.progress;active.detail=p.detail||p.title||active.detail;if(p.event==='clip_error')active.error=p.detail;save();}});
  window.__TAURI__.event.listen('progress-event',({payload:p})=>{if(!state.running)return;if(!active){active={id:crypto.randomUUID(),payload:{op:'prepare'},legacy:true,projectId:state.project?.id,projectName:state.project?.name,status:'running',progress:0};tasks.push(active);}if(!active.legacy)return;active.detail=p.detail||p.title||p.message||p.event;active.progress=p.progress??active.progress;if(p.event==='transcript_complete')active.detail=`Transcripción lista: ${p.words||p.word_count||'las'} palabras con tiempos; no es necesario repetirla.`;save();});
  window.__TAURI__.event.listen('job-finished',({payload:p})=>{if(active?.legacy)finish(p.success,p.message);});
  window.AbrxsProcesses={register(fn){runner=fn;},enqueue(payload,context,projectId){tasks.push({id:crypto.randomUUID(),payload:structuredClone({...context,...payload}),projectId,projectName:state.project?.name,status:'queued',progress:0});save();pump();},finish,mount(){const nav=document.querySelector('.ux-sidebar nav');if(nav&&!document.getElementById('processOpen')){const b=document.createElement('button');b.id='processOpen';b.textContent='◷ Procesos';b.onclick=()=>{panel.hidden=false;render();};nav.append(b);}},show(){panel.hidden=false;render();}};
  setInterval(pump,1000);
})();
